"""
Checks of signatures of contract consuming functions.
"""

from __future__ import annotations

from inspect import signature
from types import ModuleType
from typing import Any, Callable, Mapping, Union, get_args, get_origin

from .contracts import ContractData, TafContract, contracts_by_data_type

union_types: list = [Union]

try:
    from inspect import get_annotations  # type: ignore
    from types import UnionType  # type: ignore

    union_types.append(UnionType)
except ImportError:
    # We are in Python 3.9. There's no inspect.get_annotations yet.
    # We need to roll our own.

    from typing import Union

    def get_annotations(
        obj: Callable[..., object] | type[Any] | ModuleType,
        *,
        globals: Mapping[str, Any] | None = None,
        locals: Mapping[str, Any] | None = None,
        eval_str: bool = False,
    ) -> dict[str, Any]:
        # This is a low-effort backport of get_annotations from Python 3.10
        # It is only able to find annotations for the arguments that are
        # annotated with TAF contract types, or an union of them
        unevaluated = obj.__annotations__

        if not eval_str:
            return unevaluated

        known_classes = {
            data_type.__name__: data_type for data_type in contracts_by_data_type
        }
        evaluated = {}
        for name, annotation in unevaluated.items():
            if not isinstance(annotation, str):
                continue
            evaluated[name] = _convert_annotation(annotation, known_classes)

        return unevaluated | evaluated

    def _convert_annotation(annotation, known_classes):
        if annotation in known_classes:
            return known_classes[annotation]

        if annotation.startswith("Union[") and annotation.endswith("]"):
            # Old-style union
            types = [
                name.strip()
                for name in annotation.removeprefix("Union[")
                .removesuffix("]")
                .split(",")
            ]
        elif "|" in annotation:
            # New-style union
            types = [name.strip() for name in annotation.split("|")]
        else:
            return annotation

        if any(type_name not in known_classes for type_name in types):
            # Skip if any of the union types is not TAF contract type
            return annotation

        concrete_types = tuple(known_classes[type_name] for type_name in types)
        return Union[concrete_types]  # type: ignore


class InvalidConsumerSignature(Exception):
    """Base class of exceptions raised if a wrong signature for a contract is given."""


class BadContractArg(InvalidConsumerSignature):
    """Used whenever a contract argument is not found in the function signature.

    Example::

        @contract_consumer(contract_arg="my_contract_arg")
        def my_function(not_my_contract_arg: TafContract) -> None:
            pass

    This will raise a ``BadContractArg`` exception, since ``my_contract_arg``, as
    specified to the ``@contract_consumer`` decorator, is not present within
    ``my_function`` signature.
    """

    def __init__(self, contract_arg: str, func_name: str) -> None:
        super().__init__(
            f"specified argument {contract_arg!r} not found "
            f"in the signature of function {func_name}."
        )


class MissingContractType(InvalidConsumerSignature):
    """Used whenever a contract argument is missing a contract type annotation.

    Example::

        @contract_consumer(contract_arg="my_contract_arg")
        def my_function(my_contract_arg) -> None:
            pass

    This will raise a ``MissingContractType`` exception, since ``my_contract_arg``
    is missing the contract type annotation. An example of a correct signature
    would be::

        @contract_consumer(contract_arg="my_contract_arg")
        def my_function(my_contract_arg: SshClientConfig) -> None:
            pass
    """

    def __init__(self, contract_arg: str, func_name: str) -> None:
        super().__init__(
            f"specified contract argument {contract_arg!r} is missing "
            f"a contract type annotation (function {func_name!r}."
        )


class BadContractType(InvalidConsumerSignature):
    """Used whenever a contract argument has a non-contract type annotation.

    Example::

        @contract_consumer(contract_arg="my_contract_arg")
        def my_function(my_contract_arg: str) -> None:
            pass

    This will raise a ``BadContractType`` exception, since ``my_contract_arg``
    is annotated with a type that is not a contract data class or union of
    such. An example of a correct signature would be::

        @contract_consumer(contract_arg="my_contract_arg")
        def my_function(my_contract_arg: SshClientConfig) -> None:
            pass
    """

    def __init__(self, contract_arg: str, annotation: Any, func_name: str) -> None:
        super().__init__(
            f"specified contract argument {contract_arg!r} has a non-contract "
            f"type annotation: {annotation!r} (function {func_name!r})"
        )


def is_union(typ: type) -> bool:
    return get_origin(typ) in union_types


def is_taf_contract_data_type(typ: type) -> bool:
    # We don't want things like `issbuclass(str, TafContract)` to be True.
    return typ is TafContract or typ in contracts_by_data_type


def is_taf_contract_union(typ: type) -> bool:
    return is_union(typ) and all(
        is_taf_contract_data_type(subtype) for subtype in get_args(typ)
    )


def get_supported_data_types(
    func: Callable, contract_arg: str
) -> list[type[ContractData]]:
    """Get the supported contract data types for the given function.

    :raises BadContractArg: if the contract argument is not found in the
        function signature.
    :raises MissingContractType: if the contract argument is missing a contract
        type annotation.
    :raises BadContractType: if the contract argument has a non-contract type
        annotation.
    """
    func_sig = signature(func)
    if contract_arg not in func_sig.parameters:
        raise BadContractArg(contract_arg, func.__name__)

    annotations = get_annotations(func, eval_str=True)

    if contract_arg not in annotations:
        raise MissingContractType(contract_arg, func.__name__)

    data_annotation = annotations[contract_arg]

    if (
        not is_taf_contract_data_type(data_annotation)
        and not is_taf_contract_union(data_annotation)
        and not (
            isinstance(data_annotation, list)
            and not all(is_taf_contract_data_type(p) for p in data_annotation)
        )
    ):
        raise BadContractType(contract_arg, data_annotation, func.__name__)

    if not isinstance(data_annotation, list) and is_taf_contract_union(data_annotation):
        data_types = list(get_args(data_annotation))
    elif not isinstance(data_annotation, list):
        data_types = [data_annotation]
    else:
        data_types = data_annotation

    return data_types
